    "knowledgeEditor.chunking.title": "Chunking Settings",
    "knowledgeEditor.chunking.description": "Controls how uploaded documents are split before embedding. Defaults work for most cases — tune only when retrieval quality is off.",
    "knowledgeEditor.chunking.sizeLabel": "Chunk Size",
    "knowledgeEditor.chunking.sizeDescription": "Maximum characters per chunk (100–4000). Default 512 ≈ 100–130 English tokens. Smaller for FAQs (200–400), larger for narrative documents (1000–2000).",
    "knowledgeEditor.chunking.characters": "characters",
    "knowledgeEditor.chunking.overlapLabel": "Chunk Overlap",
    "knowledgeEditor.chunking.overlapDescription": "Characters shared between adjacent chunks (0–500). Default 80 ≈ 15% of size — sweet spot per current research. Use 0 for FAQs/structured data, 150–200 for long-form narratives.",
    "knowledgeEditor.chunking.separatorsLabel": "Separators",
    "knowledgeEditor.chunking.separatorsDescription": "Characters or strings the splitter prefers when cutting. Higher-priority separators are tried first; the default order favors paragraph → sentence → punctuation breaks.",
    "knowledgeEditor.chunking.separatorsPlaceholder": "Select or customize separators",
    "knowledgeEditor.chunking.separators.doubleNewline": "Double newline ()",
