    "knowledgeEditor.chunking.separators.semicolonEn": "Semicolon (;)",
    "knowledgeEditor.chunking.separators.space": "Space ( )",
    "knowledgeEditor.chunking.parentChildLabel": "Parent-Child Chunking",
    "knowledgeEditor.chunking.parentChildDescription": "Two-level chunking: small child chunks are vector-matched (precise hits) but the larger parent chunk is returned to the LLM (richer context). Recommended for long documents (>10 pages); skip for short FAQs to save storage.",
    "knowledgeEditor.chunking.parentChunkSizeLabel": "Parent Chunk Size",
    "knowledgeEditor.chunking.parentChunkSizeDescription": "Size of the context chunk returned to the LLM (512–8192). Default 4096 ≈ 1000 English tokens, fits comfortably in any modern LLM context window.",
    "knowledgeEditor.chunking.childChunkSizeLabel": "Child Chunk Size",
    "knowledgeEditor.chunking.childChunkSizeDescription": "Size of the embedded chunk used for vector match (64–2048). Default 384 ≈ 80 tokens — sweet spot for sentence-transformer / BGE-style embedders.",
    "knowledgeEditor.chunking.strategyLabel": "Chunking Strategy",
    "knowledgeEditor.chunking.strategyDescription": "Choose how documents are split into chunks. The Automatic mode profiles each document and picks the best strategy.",
    "knowledgeEditor.chunking.strategyPlaceholder": "Select a chunking strategy (splits by length if left empty)",
    "knowledgeEditor.chunking.strategies.auto.label": "Automatic",
    "knowledgeEditor.chunking.strategies.auto.tooltip": "A document profiler picks between heading-aware, structure-aware and length-based splitting per upload.",
    "knowledgeEditor.chunking.strategies.heading.label": "Heading-aware",
    "knowledgeEditor.chunking.strategies.heading.tooltip": "Splits at Markdown heading boundaries (#, ##, ###); each chunk carries its heading path. Best for well-structured Markdown.",
    "knowledgeEditor.chunking.strategies.heuristic.label": "Structure-aware",
    "knowledgeEditor.chunking.strategies.heuristic.tooltip": "Splits on detected structural cues: page-breaks, numbered sections, multilingual chapter markers (DE/EN/ZH), all-caps titles. Ideal for PDFs without Markdown headings.",
    "knowledgeEditor.chunking.strategies.legacy.label": "Length-based",
    "knowledgeEditor.chunking.strategies.legacy.tooltip": "Ignores structure; splits recursively by character count and separators — the original behavior. Use when the structure-aware strategies misbehave on your content.",
    "knowledgeEditor.chunking.overlapWarning": "Overlap is large compared to chunk size — chunks will share most of their content.",
    "knowledgeEditor.chunking.advancedLabel": "Advanced options",
    "knowledgeEditor.chunking.tokenLimitLabel": "Token limit per chunk",
    "knowledgeEditor.chunking.tokenLimitDescription": "Hard token cap per chunk (0–8192). 0 = off (chunk size in characters only). Activate when your embedding model has a small token limit: 200 for MiniLM (256 tok), 400 for BGE/Cohere (512 tok). Modern embedders (OpenAI, Voyage, Jina-v3) accept >2000 tokens — leave at 0.",
    "knowledgeEditor.chunking.languagesLabel": "Language hints",
